def localized_text(key, language):
    columns = ('en', 'zh', 'zh-Hans', 'ja', 'th')
    column = columns.index(language) if language in columns else 0
    values = TEXT[key]
    return values[column] if column < len(values) else values[0]


def translate(key, **values):
    from uav_downloader.i18n.locales import get_lang
    return localized_text(key, get_lang()).format(**values)
